 blob=subprocess.check_output(['git','-C',str(repo),'show',base+':'+name]);old=hashlib.sha256(blob).hexdigest();current=hashlib.sha256((repo/name).read_bytes().replace(b'\r\n',b'\n')).hexdigest();textNormalized=hashlib.sha256(blob.replace(b'\r\n',b'\n')).hexdigest();exact=sha(repo/name)==old
